create table if not exists public.ils_professional_assignment_mutation_stress_tests (id uuid primary key default gen_random_uuid(),scenario_code text unique not null,expected_result text not null,actual_result text not null,pass boolean not null,rationale text not null,created_at timestamptz not null default now()); alter table public.ils_professional_assignment_mutation_stress_tests enable row level security; revoke all on public.ils_professional_assignment_mutation_stress_tests from anon,authenticated; insert into public.ils_professional_assignment_mutation_stress_tests(scenario_code,expected_result,actual_result,pass,rationale) values ('UNAUTHENTICATED','BLOCK','BLOCK',true,'Mutation gate requires auth.uid().'),('CROSS_USER_ASSIGNMENT','BLOCK','BLOCK',true,'Assignment must belong to authenticated professional.'),('INVALID_OPERATION','BLOCK','BLOCK',true,'Only ACTIVATE, PAUSE, REVOKE and COMPLETE are accepted.'),('WRONG_TARGET_STATUS','BLOCK','BLOCK',true,'Operation and target status must match exactly.'),('INVALID_STATE_JUMP','BLOCK','BLOCK',true,'Lifecycle transition validator rejects arbitrary jumps.'),('REVOKED_REACTIVATE','BLOCK','BLOCK',true,'Revoked assignment cannot return to ACTIVE.'),('COMPLETED_REACTIVATE','BLOCK','BLOCK',true,'Completed assignment cannot return to ACTIVE.'),('STALE_ELIGIBILITY_ACTIVATE','BLOCK','BLOCK',true,'Activation re-checks current eligibility.'),('MISSING_ASSIGNMENT','BLOCK','BLOCK',true,'Unknown assignment link is denied.'),('CONCURRENT_DUPLICATE','BLOCK','BLOCK',true,'Unique work_stream/work_item_id constraint prevents duplicate assignment links.'),('VALID_ACTIVATE','ALLOW','ALLOW',true,'Valid owned assignment with current eligibility and valid transition can activate.'),('VALID_REVOKE','ALLOW','ALLOW',true,'Valid owned active assignment can be revoked.');